const thinkers=[{"id": "diog", "name": "Diógenes", "era": "c. 412–323 a. C.", "image": "av_npc.webp", "idea": "Filósofo cínico originario de Sinope. Defendía vivir según la naturaleza, con lo mínimo, y se burlaba de las convenciones sociales. La tradición cuenta que dormía en un gran tonel y que caminaba con una lámpara en pleno día buscando a un se"}, {"id": "beau", "name": "Simone de Beauvoir", "era": "1908–1986", "image": "av_beau.webp", "idea": "Filósofa, escritora y feminista francesa. Con El segundo sexo (1949) mostró que gran parte de lo que se considera «femenino» es una construcción social e histórica. Defendió que la libertad de las mujeres exige cambiar las condiciones que l"}, {"id": "camus", "name": "Camus", "era": "1913–1960", "image": "av_camus.webp", "idea": "Escritor y filósofo franco-argelino, criado en Argelia. Pensó el absurdo: el choque entre nuestro deseo de sentido y el silencio del mundo. Rechazó tanto la resignación como el «salto de fe» y propuso la rebeldía lúcida y la solidaridad."}, {"id": "aver", "name": "Averroes", "era": "1126–1198", "image": "av_aver.webp", "idea": "Ibn Rushd nació en Córdoba (al-Ándalus). Fue juez y médico, y comentó casi toda la obra de Aristóteles, por lo que en Europa lo llamaron «el Comentador». Defendió que la filosofía y la religión no se contradicen: cada una llega a la verdad "}, {"id": "ockh", "name": "Guillermo de Ockham", "era": "c. 1287–1347", "image": "av_ockh.webp", "idea": "Nació en Ockham (Inglaterra) y fue fraile franciscano. Sostuvo que solo existen cosas individuales y que los universales son nombres (nominalismo). Su principio de economía se conoce como la navaja de Ockham. Chocó con el papa Juan XXII y m"}, {"id": "rous", "name": "Rousseau", "era": "1712–1778", "image": "av_rous.webp", "idea": "Nació en Ginebra. Sostuvo que el ser humano nace libre y con una bondad natural (compasión, amor de sí) que la desigualdad y las instituciones sociales tienden a corromper. Propuso un contrato social basado en la voluntad general y una educ"}, {"id": "plat", "name": "Platón", "era": "427–347 a. C.", "image": "av_plat.webp", "idea": "Exploró la relación entre apariencia, conocimiento, justicia y el mundo de las Formas. Su alegoría de la caverna reflexiona sobre la educación y el difícil tránsito hacia un conocimiento más riguroso."}, {"id": "socr", "name": "Sócrates", "era": "c. 469–399 a. C.", "image": "av_socr.webp", "idea": "Sus diálogos ponen a prueba definiciones, supuestos y modos de vivir."}, {"id": "aris", "name": "Aristóteles", "era": "384–322 a. C.", "image": "av_aris.webp", "idea": "Reflexionó sobre conocimiento, causas, ética y formas de vida en comunidad."}, {"id": "agus", "name": "Agustín de Hipona", "era": "354–430", "image": "av_agus.webp", "idea": "Investigó la interioridad, la memoria, el tiempo y la relación entre fe y razón."}, {"id": "toma", "name": "Tomás de Aquino", "era": "1225–1274", "image": "av_toma.webp", "idea": "Desarrolló argumentos filosóficos sobre Dios y la relación entre filosofía y teología."}, {"id": "desc", "name": "René Descartes", "era": "1596–1650", "image": "av_desc.webp", "idea": "Con su duda metódica buscó un punto de certeza desde el que fundamentar el conocimiento."}, {"id": "hume", "name": "David Hume", "era": "1711–1776", "image": "av_hume.webp", "idea": "Analizó la experiencia, las impresiones y los límites de nuestras inferencias."}, {"id": "kant", "name": "Immanuel Kant", "era": "1724–1804", "image": "av_kant.webp", "idea": "Investigó las condiciones que hacen posible nuestra experiencia del conocimiento."}, {"id": "nietz", "name": "Friedrich Nietzsche", "era": "1844–1900", "image": "av_nietz.webp", "idea": "Examinó la crisis de los valores tradicionales y la posibilidad de nuevas formas de afirmación de la vida."}, {"id": "sartre", "name": "Jean-Paul Sartre", "era": "1905–1980", "image": "av_sartre.webp", "idea": "Pensó la libertad humana, la situación y nuestra responsabilidad al elegir."}, {"id": "fouc", "name": "Michel Foucault", "era": "1926–1984", "image": "av_fouc.webp", "idea": "Investigó históricamente la relación entre saber, poder, vigilancia y formación de sujetos."}];
