interface Save {positions:Record<string,number>;level:Place;flags:Record<string,boolean>;learned:string[];met:string[];memories:string[];seen:Place[];userScenes:Record<string,{items:Item[];regions:Region[]}>}
const storage=profileKey('sofia_phaser_real_v02');
let save:Save={positions:{},level:'polis',flags:{},learned:[],met:[],memories:[],seen:['polis'],userScenes:{}};
try{const s=JSON.parse(localStorage.getItem(storage)||'null') as Partial<Save>|null;if(s&&s.level&&s.level!=='universal'&&levels[s.level])save={...save,...s,flags:s.flags||{},learned:s.learned||[],met:s.met||[],memories:s.memories||[],seen:s.seen||['entrance'],userScenes:s.userScenes||{}}}catch{}
