if(save.flags.freed)save.flags.caveKey=true;
if(!save.positions||typeof save.positions!=='object'||Array.isArray(save.positions))save.positions={};
for(const [key,x] of Object.entries(save.positions))if(!Number.isFinite(x)||x<0||x>10000)delete save.positions[key];
