function resumeGame(){setProgressWrites(true);if(PLAY_MODE==='story'&&universe?.world?.role!=='home')universe?.openStoryMap();else{document.body.classList.remove('story-selecting');closeModal();gameScene?.presentIntroduction?.()}}
const menus=startMenu({show:html=>modal(html,'dark'),save:()=>saveGame(false),resume:resumeGame,close:closeModal,note,reload:start=>{setProgressWrites(false);if(start)sessionStorage.setItem('sofia-start-slot','1');location.reload()}});
