function unlock(kind:'idea'|'mentor'|'memory',id:string){let array=kind==='idea'?save.learned:kind==='mentor'?save.met:save.memories;if(!array.includes(id)){array.push(id);store();note('✦ Nuevo descubrimiento para tu colección')}}
function mark(id:string){save.flags[id]=true;store();hud()}
function hud(){if(universe?.active){const inside=!!universe.progress.interior;document.body.classList.toggle('radial',!inside);el('planet-exit').hidden=(!inside&&!universe.canReturnPortal)||(inside&&!!universe.world!.journey?.physicalDoors);el('planet-exit').textContent=!inside||(universe.canReturnPortal&&!universe.progress.trail.length&&universe.progress.entryPortalScene===universe.progress.interior)?'Volver al portal':universe.progress.trail.at(-1)?.interior?'Volver al escenario anterior':'Volver al planeta';el('planet-view').hidden=inside;el('chapter').textContent=universe.world!.title;document.querySelector('footer span:last-child')!.textContent=universe.world!.title;return}document.querySelector('footer span:last-child')!.textContent='Miniplaneta de la Polis · Phaser 3';el('planet-exit').textContent=cavePrevious[save.level]&&cavePrevious[save.level]!=='polis'?'Volver al escenario anterior':'Salir a la Polis';document.body.classList.toggle('radial',save.level==='polis');el('planet-exit').hidden=save.level==='polis'||(!planetState.returnAnchor&&!cavePrevious[save.level]);el('planet-view').hidden=save.level!=='polis';if(save.level==='polis'&&universe?.canReturnPortal){el('planet-exit').hidden=false;el('planet-exit').textContent='Volver al portal'}let message='';const f=save.flags;if(save.level==='polis')message='Explora la circunferencia y conversa con Sócrates.';else if(save.level==='entrance')message=f.lamp?'Entra en la cámara de sombras.':'Encuentra y enciende tu lámpara.';else if(save.level==='shadows')message=!f.prisoner?'Conversa con el prisionero.':!f.shadows?'Investiga el origen de las sombras.':!f.freed?'Libera al prisionero.':'Encuentra el sendero hacia la luz.';else if(save.level==='ascent')message='Sube las escaleras y sigue la luz.';else if(save.level==='exterior')message=f.plato?'Explora otros mundos.':'Habla con Platón.';else message='Conversa con el pensador y explora.';
 el('quest').textContent='□ '+message;el('chapter').textContent=levels[save.level].name.toUpperCase();el('progress-title').textContent=save.level==='library'?'Biblioteca':save.level==='exterior'?'La luz':'La caverna';el('subchapter').textContent=levels[save.level].subtitle;
 const n=save.level==='entrance'?0:save.level==='shadows'?1:save.level==='ascent'?2:3;Array.from(el('milestones').children).forEach((x,i)=>x.classList.toggle('active',i<=n));el('xp-bar').style.width=Math.min(95,20+save.learned.length*14+save.met.length*8)+'%'}
function warp(next:Place){if(PLAY_MODE==='story'&&['medieval','modern','contemporary'].includes(next)){note('Estas visitas están disponibles en el modo Libre.');return}if(!gameScene){note('El escenario se está preparando. Inténtalo en un momento.');return}if(!universe?.active&&save.level==='ascent'&&next==='exterior'&&save.flags.freed)mark('caveCompleted');if(universe?.active)universe.deactivate();closeModal();setChangingScene(true);hasModal=true;control.left=false;control.right=false;control.jump=false;control.axis=0;editing=false;document.body.classList.remove('editing');el('editor').hidden=true;save.level=next;if(!save.seen.includes(next))save.seen.push(next);store();gameScene.scene.start(next==='polis'?'Planet':'World',{place:next});hud()}
function intro(){modal(`<div class="splash-text"><div class="eyebrow">AVENTURA FILOSÓFICA · EL PRIMER PLANETA</div><h1>Sofía y los mundos de las ideas</h1><p>Una pequeña astronauta sigue una brújula que no busca el norte: busca preguntas. En un pequeño planeta descubrirá su primer desafío.</p>${buttons(['start',save.flags.plato?'Continuar viaje':'Comenzar aventura'],['map','Galaxia de las ideas'])}<p><small>Toca el lugar al que quieras ir. Toca objetos y personajes para descubrirlos.</small></p></div><img class="hero" src="assets/sofia_7.png" alt="Sofía">`,'splash');action('start',()=>{save.flags.intro=true;store();closeModal();if(save.level==='polis')universe?.legacyWelcome()});action('map',atlas)}
const cavePrevious:Partial<Record<Place,Place>>={entrance:'polis',shadows:'entrance',ascent:'shadows',exterior:'ascent',library:'polis'};
let legacyArrival:number|undefined;
