function talkWarden(){
 if(save.flags.caveKey){modal(`<img class="portrait" src="assets/portrait-warden.png" alt="Guardián"><div class="character-tag">Guardián de las sombras</div><p>—Ya tienes la llave. Lo que hagas con ella también será una forma de responder a lo que has aprendido.</p>${buttons(['close','Volver con el prisionero'])}`,'story');action('close',closeModal);return}
 if(!save.flags.shadows){modal(`<img class="portrait" src="assets/portrait-warden.png" alt="Guardián"><div class="character-tag">Guardián de las sombras</div><p>—Antes de pedir una llave, mira cómo nacen las sombras. Escucha al prisionero y relaciona cada silueta con el objeto que la produce.</p>${buttons(['close','Investigar el origen de las sombras'])}`,'story');action('close',closeModal);return}
 modal(`<img class="portrait" src="assets/portrait-warden.png" alt="Guardián"><div class="character-tag">Guardián de las sombras</div><h2>Una llave y una distinción</h2><p>—Una opinión puede resultar verdadera, pero repetirla no es lo mismo que justificarla. Si distingues doxa y episteme, te confiaré la llave.</p>${buttons(['trial','Examinar las afirmaciones'],['close','Seguir investigando'])}`,'story');action('trial',()=>{knowledgeStep=0;renderKnowledgeTrial()});action('close',closeModal)
}
