function renderPuzzle(){if(puzzleStep===3){mark('shadows');unlock('idea','appearance');modal(`<div class="eyebrow">DESCUBRIMIENTO</div><h2>¡Las sombras tienen un origen!</h2><p>Las siluetas dependían de objetos y de la luz. Tus primeras impresiones no bastaban para conocer lo que sucedía.</p><div class="tag-reward"><b>✦ Apariencia y realidad</b><p>Has desbloqueado tu primera idea filosófica.</p></div>${buttons(['close','Continuar la aventura'])}`);action('close',closeModal);return}
 const answer=puzzle[puzzleStep];modal(`<div class="eyebrow">MINIJUEGO · LAS SOMBRAS</div><h2>¿Qué produce esta sombra?</h2><p>Observa la imagen y selecciona su causa.</p><div class="mini-steps">${puzzle.map((_,i)=>`<i class="${i<puzzleStep?'ok':''}"></i>`).join('')}</div><div class="mini-layout"><div class="shadow-art"><img src="assets/${answer[1]}" alt="Silueta de la caverna"></div><div class="options">${puzzle.map(([name])=>`<button data-answer="${name}">${name}</button>`).join('')}</div></div><p id="feedback">Reconoce los contornos antes de responder.</p>${buttons(['close','Salir del reto'])}`);document.querySelectorAll('[data-answer]').forEach(b=>(b as HTMLButtonElement).onclick=()=>{if((b as HTMLButtonElement).dataset.answer===answer[0]){puzzleStep++;renderPuzzle()}else el('feedback').textContent='Esa no parece la causa de la sombra. Inténtalo de nuevo.'});action('close',closeModal)}
function talkPlato(){mark('plato');unlock('mentor','plat');unlock('idea','allegory');unlock('idea','opinion');unlock('memory','light');modal(`<img class="portrait" src="assets/portrait-plat.png" alt="Platón"><div class="character-tag">Platón · Mentor</div><h2>«Conocer exige volver a preguntar»</h2><p>—La caverna es una alegoría de la educación. Las sombras nos recuerdan que nuestras primeras creencias pueden ser insuficientes.</p><p>—Sofía, tu compañero ha comenzado a descubrir lo que existe fuera de la caverna. Aquí concluye el rescate: el prisionero se queda en libertad junto a la salida. Me encontrarás aquí cuando quieras conversar sobre lo que has descubierto.</p><div class="tag-reward"><b>✦ Platón desbloqueado · Nuevos conceptos y recuerdos</b></div>${buttons(['album','Ver mis descubrimientos'],['return-cave','Volver a visitar la caverna'],['map','Ver los mundos'])}`,'story');action('album',()=>collection('philosophers'));action('return-cave',()=>warp('shadows'));action('map',atlas)}
function interactWith(item:Item){gameScene?.faceCharacter?.(item.characterId??item.id);if(universe?.active){universe.interact(item.id);return}if(item.type==='lamp'){mark('lamp');modal(`<div class="eyebrow">DESCUBRIMIENTO</div><h2>Una lámpara encendida</h2><p>Sofía ilumina la caverna. La luz permite distinguir objetos que antes permanecían ocultos.</p>${buttons(['close','Seguir explorando'])}`);action('close',closeModal)}
 else if(item.type==='door'){if(item.id==='planet-return'){returnLegacy();return}if(item.id==='gate'&&save.level==='entrance'&&!save.flags.lamp){note('Enciende antes tu lámpara.');return}if(item.id==='gate'&&save.level==='shadows'&&!save.flags.freed){note('Ayuda primero al prisionero.');return}if(item.to)warp(item.to)}
 else if(item.type==='warden')talkWarden();else if(item.type==='prisoner')talkPrisoner();else if(item.type==='shadows'){if(save.flags.prisoner)puzzleGame();else note('Habla primero con el prisionero.')}else if(item.type==='chains')freePrisoner()
 else if(item.type==='stair')gameScene?.climb?.();else if(item.type==='plato')talkPlato();else if(item.type==='ship')void boardCurrentShip(item);else if(item.type==='philosopher'){const id=item.who||'socr';unlock('mentor',id);if(id==='agus')unlock('idea','memory');if(id==='desc')unlock('idea','doubt');if(id==='fouc')unlock('idea','power');const p=thinkers.find(x=>x.id===id);modal(`<img class="portrait" src="assets/${p?.image||'portrait-socr.png'}"><div class="character-tag">${p?.name||'Filósofo'}</div><h2>Una nueva pregunta</h2><p>${p?.idea||'Toda pregunta merece atención.'}</p><p>Este es un escenario de exploración. Su misión completa aún está por desarrollar.</p>${buttons(['close','Continuar'])}`);action('close',closeModal)}else modal(`<div class="eyebrow">OBJETO DEL ENTORNO</div><h2>${item.label}</h2><p>Los objetos también permiten descubrir cómo vivían y pensaban los habitantes del lugar.</p>${buttons(['close','Continuar'])}`),action('close',closeModal)}
